"use client";

import { useState, useEffect } from "react";
import {
  Search,
  ChevronUp,
  ChevronDown,
  Edit,
  Trash2,
  AlertCircle,
  Loader2,
  UserCircle,
  Flag,
  Briefcase,
  Home,
  RefreshCw,
  Download,
  MapPin,
  Lock,
  Filter,
  X,
  CalendarIcon,
  MapPinIcon,
  BuildingIcon,
  PhoneIcon,
  MailIcon,
  DollarSign,
  UserMinus,
} from "lucide-react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import * as XLSX from "xlsx";
import { QRCodeCanvas } from "qrcode.react";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import Layout from "../Layout";
import logo from "../../../assets/logo1.png";

export default function Interns() {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState("");
  const [interns, setInterns] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [sortField, setSortField] = useState("First_Name");
  const [sortDirection, setSortDirection] = useState("asc");
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [isBadgeModalOpen, setIsBadgeModalOpen] = useState(false);
  const [selectedIntern, setSelectedIntern] = useState(null);
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordError, setPasswordError] = useState("");
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isFlipped, setIsFlipped] = useState(false);
  const [filterSector, setFilterSector] = useState("");
  const [filterYear, setFilterYear] = useState("");

  useEffect(() => {
    fetchInterns();
  }, []);

  const fetchInterns = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    if (!token) {
      setError("Authentification requise. Veuillez vous connecter.");
      setIsLoading(false);
      return;
    }

    try {
      const response = await axios.get(
        `${process.env.REACT_APP_API_URL}/api/interns?includePassword=true`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        }
      );
      if (response.data.success) {
        setInterns(response.data.data || []);
      } else {
        setError(
          "Échec de la récupération des stagiaires : " + response.data.message
        );
      }
    } catch (err) {
      setError(
        `Erreur lors de la récupération des stagiaires : ${
          err.response?.data?.message || err.message
        }`
      );
      console.error("Erreur de récupération des stagiaires :", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const handleEditIntern = (id) => {
    navigate(`/EditIntern/${id}`);
  };

  const handleDeleteIntern = async (id) => {
    if (window.confirm("Êtes-vous sûr de vouloir supprimer ce stagiaire ?")) {
      try {
        const token = localStorage.getItem("token");
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/interns/${id}`, {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        });
        setInterns(interns.filter((intern) => intern._id !== id));
        setError("");
      } catch (err) {
        setError(
          "Échec de la suppression du stagiaire : " +
            (err.response?.data?.message || err.message)
        );
      }
    }
  };

  const handleRemoveInternToFormer = async (id, firstName, lastName) => {
    if (
      window.confirm(
        `Êtes-vous sûr de vouloir retirer ${firstName} ${lastName} de la liste des stagiaires actifs ? Cette action calculera leur paiement total, enregistrera leurs données dans les anciens stagiaires avec la date d'entrée (date de création) et la date de sortie (aujourd'hui), et supprimera leurs données des stagiaires actifs.`
      )
    ) {
      try {
        const token = localStorage.getItem("token");
        const response = await axios.post(
          `${process.env.REACT_APP_API_URL}/api/interns/${id}/remove-to-former`,
          {},
          {
            headers: {
              Authorization: `Bearer ${token}`,
              Role: "Deputydirector",
            },
          }
        );
        if (response.data.success) {
          setInterns(interns.filter((intern) => intern._id !== id));
          setError("");
        } else {
          setError(
            "Échec du déplacement du stagiaire vers anciens stagiaires : " +
              response.data.message
          );
        }
      } catch (err) {
        setError(
          "Échec du déplacement du stagiaire vers anciens stagiaires : " +
            (err.response?.data?.message || err.message)
        );
      }
    }
  };

  const handleCalculateAndResetPayments = async () => {
    if (
      window.confirm(
        "Vous êtes sur le point de calculer le paiement total pour chaque stagiaire et de réinitialiser leurs paiements mensuels à zéro. Cette action mettra à jour le champ 'Total Paiement' pour chaque stagiaire et réinitialisera les montants mensuels dans la collection des paiements. Voulez-vous continuer ?"
      )
    ) {
      try {
        const token = localStorage.getItem("token");
        const response = await axios.post(
          `${process.env.REACT_APP_API_URL}/api/interns/calculate-and-reset-payments`,
          {},
          {
            headers: {
              Authorization: `Bearer ${token}`,
              Role: "Deputydirector",
            },
          }
        );
        if (response.data.success) {
          await fetchInterns();
          setError("");
        } else {
          setError(
            "Échec du calcul et de la réinitialisation des paiements : " +
              response.data.message
          );
        }
      } catch (err) {
        setError(
          "Échec du calcul et de la réinitialisation des paiements : " +
            (err.response?.data?.message || err.message)
        );
      }
    }
  };

  const openDetailsModal = (intern) => {
    setSelectedIntern(intern);
    setIsDetailsModalOpen(true);
    setPasswordError("");
  };

  const closeDetailsModal = () => {
    setIsDetailsModalOpen(false);
    setSelectedIntern(null);
    setIsPasswordModalOpen(false);
    setNewPassword("");
    setConfirmPassword("");
    setPasswordError("");
  };

  const openPasswordModal = () => {
    setIsPasswordModalOpen(true);
    setNewPassword("");
    setConfirmPassword("");
    setPasswordError("");
  };

  const closePasswordModal = () => {
    setIsPasswordModalOpen(false);
    setNewPassword("");
    setConfirmPassword("");
    setPasswordError("");
  };

  const handleUpdatePassword = async () => {
    if (newPassword !== confirmPassword) {
      setPasswordError("Les mots de passe ne correspondent pas.");
      return;
    }

    if (newPassword.length < 6) {
      setPasswordError("Le mot de passe doit contenir au moins 6 caractères.");
      return;
    }

    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setPasswordError("Authentification requise. Veuillez vous connecter.");
        return;
      }

      const response = await axios.put(
        `${process.env.REACT_APP_API_URL}/api/interns/${selectedIntern._id}/password`,
        { password: newPassword },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        }
      );

      if (response.data.success) {
        setPasswordError("");
        closePasswordModal();
      } else {
        setPasswordError(
          response.data.message || "Échec de la mise à jour du mot de passe."
        );
      }
    } catch (err) {
      console.error("Erreur côté frontal :", err.response?.data);
      setPasswordError(
        err.response?.data?.message ||
          "Erreur lors de la mise à jour du mot de passe."
      );
    }
  };

  const openBadgeModal = (intern) => {
    setSelectedIntern(intern);
    setIsBadgeModalOpen(true);
    setIsFlipped(false);
  };

  const closeBadgeModal = () => {
    setIsBadgeModalOpen(false);
    setSelectedIntern(null);
  };

  const handleDownloadBadge = () => {
    if (!selectedIntern.image) {
      alert("Image non trouvée");
      return;
    }

    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
    });
    const badgeContainer = document.getElementById("badge-container");
    const frontElement = document.getElementById("badge-front");
    const backElement = document.getElementById("badge-back");

    frontElement.style.visibility = "visible";
    backElement.style.visibility = "visible";
    frontElement.style.transform = "none";
    backElement.style.transform = "none";
    badgeContainer.style.transform = "none";

    const imgElement = frontElement.querySelector("img");
    if (!imgElement) {
      console.error("No image element found in badge-front");
      alert("Image non trouvée");
      return;
    }

    const captureFront = () => {
      html2canvas(frontElement, {
        scale: 2,
        backgroundColor: "#ffffff",
        logging: true,
        useCORS: true,
      })
        .then((frontCanvas) => {
          console.log(
            "Front canvas captured, size:",
            frontCanvas.width,
            frontCanvas.height
          );
          const frontImgData = frontCanvas.toDataURL("image/png");

          html2canvas(backElement, {
            scale: 2,
            backgroundColor: "#ffffff",
            logging: true,
            useCORS: true,
          })
            .then((backCanvas) => {
              console.log(
                "Back canvas captured, size:",
                backCanvas.width,
                backCanvas.height
              );
              const backImgData = backCanvas.toDataURL("image/png");

              const pageWidth = doc.internal.pageSize.getWidth();
              const badgeWidth = pageWidth / 2 - 10;
              const badgeHeight =
                (frontCanvas.height * badgeWidth) / frontCanvas.width;

              doc.addImage(frontImgData, "PNG", 5, 20, badgeWidth, badgeHeight);
              doc.addImage(
                backImgData,
                "PNG",
                pageWidth / 2 + 5,
                20,
                badgeWidth,
                badgeHeight
              );

              doc.save(
                `Badge_${selectedIntern.First_Name}_${selectedIntern.Last_Name}.pdf`
              );

              if (isFlipped) {
                frontElement.style.visibility = "hidden";
                backElement.style.visibility = "visible";
                badgeContainer.style.transform = "rotateY(180deg)";
              } else {
                frontElement.style.visibility = "visible";
                backElement.style.visibility = "hidden";
                badgeContainer.style.transform = "rotateY(0deg)";
              }
            })
            .catch((error) => {
              console.error("Error capturing back:", error);
              alert("Erreur lors de la capture du verso du badge");
            });
        })
        .catch((error) => {
          console.error("Error capturing front:", error);
          alert("Erreur lors de la capture du recto du badge");
        });
    };

    if (imgElement.complete && imgElement.naturalWidth !== 0) {
      console.log("Image already loaded, capturing front...");
      captureFront();
    } else {
      console.log("Waiting for image to load...");
      imgElement.onload = () => {
        console.log("Image loaded, capturing front...");
        captureFront();
      };
      imgElement.onerror = () => {
        console.error("Image failed to load:", imgElement.src);
        alert("Image non trouvée");
        frontElement.style.visibility = "visible";
        backElement.style.visibility = "hidden";
        badgeContainer.style.transform = isFlipped
          ? "rotateY(180deg)"
          : "rotateY(0deg)";
      };
      imgElement.src = imgElement.src;
    }
  };

  const handleFlip = () => {
    setIsFlipped(!isFlipped);
  };

  const filteredAndSortedInterns = interns
    .filter((intern) => {
      const firstName = (intern.First_Name || "").toLowerCase();
      const lastName = (intern.Last_Name || "").toLowerCase();
      const cff = (intern.CFF || "").toLowerCase();
      const hometown = (intern.hometown || "").toLowerCase();
      const email = (intern.email || "").toLowerCase();
      const emplacement = (intern.emplacement || "").toLowerCase();
      const sector = (intern.Sector || "").toLowerCase();
      const createdYear = intern.createdAt
        ? new Date(intern.createdAt).getFullYear().toString()
        : "";

      const matchesSearch =
        `${firstName} ${lastName}`.includes(searchQuery.toLowerCase()) ||
        cff.includes(searchQuery.toLowerCase()) ||
        hometown.includes(searchQuery.toLowerCase()) ||
        email.includes(searchQuery.toLowerCase()) ||
        emplacement.includes(searchQuery.toLowerCase());
      const matchesSector =
        !filterSector || sector === filterSector.toLowerCase();
      const matchesYear = !filterYear || createdYear === filterYear;

      return matchesSearch && matchesSector && matchesYear;
    })
